      { s: "", jp: "むしろ、{浮|う}いた{時間|じかん}に{別|べつ}の{用事|ようじ}を{詰|つ}め{込|こ}み、{以前|いぜん}より{忙|いそが}しくなってはいないだろうか。", ro: "Mushiro, uita jikan ni betsu no yōji o tsumekomi, izen yori isogashiku natte wa inaidarō ka.", en: "Rather, have we not packed other tasks into the spare time and become busier than before?" },
      { s: "", jp: "{便利|べんり}さが{幸福|こうふく}に{直結|ちょっけつ}するという{考|かんが}えは、{そろそろ}{疑|うたが}ってみるべきではないか。", ro: "Benrisa ga kōfuku ni chokketsu suru toiu kangae wa, {sorosoro} utagatte miru beki dehanai ka.", en: "Shouldn't we begin to doubt the idea that convenience leads straight to happiness?" },
      { s: "", jp: "{立|た}ち{止|ど}まって{問|と}い{直|なお}すことこそ、{豊|ゆた}かさへの{第一歩|だいいっぽ}ではないだろうか。", ro: "Tachi domatte toinaosu koto koso, yutakasa e no daiippo dehanai darōka.", en: "Isn't stopping to ask again precisely the first step toward richness?" }
