      { s: "", jp: "{無料|むりょう}{体験|たいけん}{期間|きかん}が{終了|しゅうりょう}した{時点|じてん}で、{自動的|じどうてき}に{有料|ゆうりょう}{会員|かいいん}へ{移行|いこう}する。", ro: "Muryō taiken kikan ga shūryō shita jiten de, jidōteki ni yūryō kaiin e ikō suru.", en: "When the free trial period ends, the member automatically moves to a paid membership." },
      { s: "", jp: "{解約|かいやく}の{手続|てつづ}きが{請求日|せいきゅうび}の{前日|ぜんじつ}までに{完了|かんりょう}していない{場合|ばあい}は、{翌月|よくげつ}{分|ぶん}の{料金|りょうきん}が{発生|はっせい}する。", ro: "Kaiyaku no tetsuzuki ga seikyūbi no zenjitsu made ni kanryō shite inai baai wa, yokugetsu bun no ryōkin ga hassei suru.", en: "If cancellation has not been completed by the day before the billing date, the next month's fee arises." },
      { s: "", jp: "{支払|しはら}い{済|ず}みの{利用料|りようりょう}は、{理由|りゆう}の{如何|いかん}を{問|と}わず、{返金|へんきん}しない。", ro: "Shiharai zumi no riyōryō wa, riyū no ikan o towazu, henkin shinai.", en: "Fees already paid are not refunded, whatever the reason." },
      { s: "", jp: "ただし、{当社|とうしゃ}の{都合|つごう}によりサービスを{提供|ていきょう}できなかった{場合|ばあい}に{限|かぎ}り、{該当|がいとう}{期間|きかん}{分|ぶん}を{日割|ひわ}りで{返金|へんきん}する。", ro: "Tadashi, tōsha no tsugō ni yori sābisu o teikyō dekinakatta baai ni kagiri, gaitō kikan bun o hiwari de henkin suru.", en: "However, only where we were unable to provide the service owing to our own circumstances, the fee for the relevant period is refunded on a daily basis." },
      { s: "", jp: "{料金|りょうきん}は、{登録|とうろく}された{支払|しはら}い{方法|ほうほう}から{自動的|じどうてき}に{引|ひ}き{落|お}とされる。", ro: "Ryōkin wa, tōroku sareta shiharai hōhō kara jidōteki ni hikio to sareru.", en: "Fees are automatically deducted from the registered payment method." },
      { s: "", jp: "{支払|しはら}いが{確認|かくにん}できない{場合|ばあい}は、{七日間|なのかかん}の{猶予|ゆうよ}の{後|のち}、{利用|りよう}を{一時|いちじ}{停止|ていし}する。", ro: "Shiharai ga kakunin dekinai baai wa, nanokakan no yūyo no nochi, riyō o ichiji teishi suru.", en: "If payment cannot be confirmed, use is temporarily suspended after a grace period of seven days." },
      { s: "", jp: "{複数|ふくすう}の{端末|たんまつ}で{同時|どうじ}に{利用|りよう}できるのは、{最大|さいだい}{三台|さんだい}までとする。", ro: "Fukusū no tanmatsu de dōji ni riyō dekiru no wa, saidai sandai made to suru.", en: "Simultaneous use on multiple devices is limited to a maximum of three." },
      { s: "", jp: "{料金|りょうきん}を{改定|かいてい}する{場合|ばあい}は、{三十日前|さんじゅうにちまえ}までに{会員|かいいん}へ{通知|つうち}する。", ro: "Ryōkin o kaitei suru baai wa, sanjūnichimae made ni kaiin e tsūchi suru.", en: "When revising fees, members are notified at least thirty days beforehand." },
      { s: "", jp: "{会員|かいいん}{情報|じょうほう}の{変更|へんこう}は、{登録|とうろく}{画面|がめん}から{随時|ずいじ}{行|おこな}うことができる。", ro: "Kaiin jōhō no henkō wa, tōroku gamen kara zuiji okonau koto ga dekiru.", en: "Members may change their information at any time from the registration screen." },
      { s: "", jp: "{利用者|りようしゃ}が{規約|きやく}に{違反|いはん}したときは、{予告|よこく}なく{会員|かいいん}{資格|しかく}を{停止|ていし}することがある。", ro: "Riyōsha ga kiyaku ni ihan shita toki wa, yokokunaku kaiin shikaku o teishi suru koto ga aru.", en: "If a user violates the terms, membership may be suspended without notice." }
